<script setup lang="ts">import{Head,router}from'@inertiajs/vue3';import AdminLayout from'../../Layouts/AdminLayout.vue';defineProps<{inquiries:any}>();const update=(id:number,status:string)=>router.patch(`/admin/inquiries/${id}`,{status});</script><template><Head title="Contact Inquiries"/><AdminLayout><h1 class="text-3xl font-extrabold">Contact inquiries</h1><div class="mt-8 grid gap-5"><article v-for="i in inquiries.data" class="card"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="text-lg font-extrabold">{{i.full_name}} <span class="font-normal text-slate-500">— {{i.company_name}}</span></h2><a :href="`mailto:${i.email}`" class="text-brand-600">{{i.email}}</a> · {{i.phone}}</div><select :value="i.status" class="field !w-auto" @change="update(i.id,($event.target as HTMLSelectElement).value)"><option>new</option><option>in_progress</option><option>resolved</option><option>spam</option></select></div><h3 class="mt-5 font-bold">{{i.subject}} · {{i.service}}</h3><p class="mt-2 whitespace-pre-line text-slate-600">{{i.message}}</p></article><p v-if="!inquiries.data.length" class="card text-center">No inquiries yet.</p></div></AdminLayout></template>
